11	/// Map a React builtin type name to the appropriate `PropType`.
12	pub(super) fn react_type_to_prop_type(
13	    name: &str,
14	    args: &[CollectedType],
15	    consuming_file: &Utf8Path,
16	    ctx: &ResolutionContext,
17	    state: &mut ResolveState,
18	    depth: u8,
19	) -> PropType {
20	    // Strip "React." prefix for matching.
21	    let strip = name.strip_prefix("React.").unwrap_or(name);
22	
23	    match strip {
24	        // React node types.
25	        "ReactNode" | "ReactElement" | "JSX.Element" | "ReactPortal" | "ReactFragment" | "ReactChild" => {
26	            PropType::ReactNode
27	        }
28	
29	        // CSS properties.
30	        "CSSProperties" | "CSSObject" => PropType::CssProperties,
31	
32	        // Ref types.
33	        "Ref" | "RefObject" | "ForwardedRef" | "MutableRefObject" | "RefCallback" | "LegacyRef" => {
34	            let element = args.first().map(|a| a.to_raw_string());
35	            PropType::Ref { name: strip.to_owned(), element }
36	        }
37	
38	        // ElementType — component-as-prop.
39	        "ElementType" => PropType::ElementType,
40	
41	        // FC / FunctionComponent — return as Named.
42	        "FC"
43	        | "FunctionComponent"
44	        | "VFC"
45	        | "VoidFunctionComponent"
46	        | "ComponentType"
47	        | "ForwardRefExoticComponent" => {
48	            let resolved_args: Vec<PropType> =
49	                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
50	            PropType::Named { name: name.into(), args: resolved_args }
51	        }
52	
53	        // ComponentPropsWithoutRef<'button'> or ComponentPropsWithoutRef<typeof X>.
54	        "ComponentPropsWithoutRef" | "ComponentProps" | "ComponentPropsWithRef" => {
55	            if let Some(first) = args.first() {
56	                match first {
57	                    CollectedType::StringLiteral(el) => {
58	                        PropType::HtmlAttributes { element: el.to_lowercase().to_string(), omitted: vec![] }
59	                    }
60	                    other => PropType::Named {
61	                        name: name.into(),
62	                        args: vec![resolve_collected_type(other, consuming_file, ctx, state, depth + 1)],
63	                    },
64	                }
65	            } else {
66	                PropType::Any
67	            }
68	        }
69	
70	        // PropsWithChildren / PropsWithRef — resolve inner type.
71	        "PropsWithChildren" | "PropsWithRef" => {
72	            if let Some(first) = args.first() {
73	                resolve_collected_type(first, consuming_file, ctx, state, depth + 1)
74	            } else {
75	                PropType::Any
76	            }
77	        }
78	
79	        // ElementRef.
80	        "ElementRef" => PropType::Ref { name: "ElementRef".into(), element: None },
81	
82	        // Context / Consumer / Provider — surface as Named.
83	        "Context" | "Consumer" | "Provider" | "RefAttributes" => {
84	            let resolved_args: Vec<PropType> =
85	                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
86	            PropType::Named { name: name.into(), args: resolved_args }
87	        }
88	
89	        // Default — surface as Named with resolved args.
90	        _ => {
91	            let resolved_args: Vec<PropType> =
92	                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
93	            PropType::Named { name: name.into(), args: resolved_args }
94	        }
95	    }
96	}
