98	/// Best-effort path to the @types/react .d.ts file for RDT propFilter compat.
99	/// Falls back to a synthetic path if @types/react is not installed.
100	pub(super) fn resolve_react_types_file(from_file: &Utf8Path, ctx: &ResolutionContext) -> String {
101	    let dir = from_file.parent().map_or("", Utf8Path::as_str);
102	    if let Some(found) = ctx.react_types_files.get(dir) {
103	        return found.clone();
104	    }
105	    let found = resolve_package_types_file(&ctx.oxc_resolver, &ctx.types_first_resolver, from_file, "react")
106	        .unwrap_or_else(|| "node_modules/@types/react/index.d.ts".to_owned());
107	    ctx.react_types_files.insert(Box::from(dir), found.clone());
108	    found
109	}
