111	/// Resolve `package_name` to its declaration file the way TypeScript does. `oxc_resolver`'s `resolve_dts` stops at the
112	/// first `exports` key that matches any condition, even one pointing at JavaScript, so two retries follow: with only
113	/// the `types` conditions (`types_first`), for a package that lists `"import"` before `"types"`; then the separate
114	/// `@types/<name>` package, for one with no types of its own. A declaration file that doesn't exist counts as none.
115	pub(super) fn resolve_package_types_file(
116	    resolver: &Resolver,
117	    types_first: &Resolver,
118	    importing_file: &Utf8Path,
119	    package_name: &str,
120	) -> Option<String> {
121	    let declaration = |resolver: &Resolver, specifier: &str| {
122	        let resolved = resolver.resolve_dts(importing_file.as_std_path(), specifier).ok()?;
123	        // `resolve_dts` returns an `exports` target without checking it exists (an unbuilt workspace package's `dist`).
124	        let is_declaration =
125	            [".d.ts", ".d.mts", ".d.cts"].iter().any(|ext| resolved.path().to_string_lossy().ends_with(ext));
126	        (is_declaration && resolved.path().is_file()).then(|| resolved.path().to_string_lossy().into_owned())
127	    };
128	    declaration(resolver, package_name)
129	        .or_else(|| declaration(types_first, package_name))
130	        .or_else(|| declaration(resolver, &format!("@types/{}", mangle_scoped_package_name(package_name))))
131	}
132	
133	/// `@scope/name` -> `scope__name`, matching TypeScript's `@types` scoped-package
134	/// naming convention (e.g. `@babel/core` -> `@types/babel__core`). Unscoped names
135	/// pass through unchanged.
136	fn mangle_scoped_package_name(name: &str) -> String {
137	    name.strip_prefix('@').map_or_else(|| name.to_owned(), |rest| rest.replacen('/', "__", 1))
138	}
