225	pub(super) enum AmbientGlobalLookup<'g> {
226	    Interface,
227	    TypeAlias(&'g CollectedTypeAlias),
228	}
229	
230	/// What a specifier resolves to from one directory.
231	#[derive(Clone)]
232	pub(crate) enum ModuleResolution {
233	    /// A package's type declarations, outside the project.
234	    PackageTypes(Utf8PathBuf),
235	    /// A file of the project, or a module resolved by path.
236	    File(Utf8PathBuf),
237	    /// The resolver's error.
238	    Unresolved(String),
239	}
240	
241	/// Use `oxc_resolver` to turn an import specifier into an absolute file path.
242	pub(super) fn resolve_import_specifier(
243	    specifier: &str,
244	    from_file: &Utf8Path,
245	    ctx: &ResolutionContext,
246	    diagnostics: &mut Vec<Diagnostic>,
247	) -> Option<Utf8PathBuf> {
248	    super::deps::record_module_resolution();
249	    let from_dir = from_file.parent()?;
250	    // Every file of a directory shares its nearest tsconfig, so the directory is as good a key as the file.
251	    let key = (Box::from(from_dir.as_str()), Box::from(specifier));
252	    let resolution = match ctx.module_resolutions.get(&key) {
253	        Some(cached) => cached.clone(),
254	        None => {
255	            let resolution = resolve_module(specifier, from_file, ctx);
256	            ctx.module_resolutions.insert(key, resolution.clone());
257	            resolution
258	        }
259	    };
260	    match resolution {
261	        ModuleResolution::PackageTypes(path) => Some(path),
262	        ModuleResolution::File(path) => {
263	            super::deps::record(&path);
264	            Some(path)
265	        }
266	        ModuleResolution::Unresolved(error) => {
267	            diagnostics.push(
268	                Diagnostic::new(
269	                    DiagnosticSeverity::Warning,
270	                    DiagnosticCode::UnresolvableImport,
271	                    format!("Cannot resolve '{}' from '{}'", specifier, from_file),
272	                )
273	                .with_file(from_file.to_string())
274	                .with_help(format!("Resolution error: {}", error)),
275	            );
276	            None
277	        }
278	    }
279	}
280	
281	/// Resolve `specifier` as imported by `from_file`; the file, not its directory, is what finds the nearest tsconfig.
282	fn resolve_module(specifier: &str, from_file: &Utf8Path, ctx: &ResolutionContext) -> ModuleResolution {
283	    resolve_module_with(&ctx.oxc_resolver, &ctx.types_first_resolver, specifier, from_file)
284	}
285	
286	/// `resolve_module` with explicit resolvers (`ModuleResolvers`): the dependency loader resolves before a
287	/// `ResolutionContext` exists and must find the same files the resolver later does.
288	pub(crate) fn resolve_module_with(
289	    main: &oxc_resolver::Resolver,
290	    types_first: &oxc_resolver::Resolver,
291	    specifier: &str,
292	    from_file: &Utf8Path,
293	) -> ModuleResolution {
294	    // Bare package specifiers (not relative/absolute) need real TypeScript
295	    // declaration resolution: prefer a real .d.ts over whatever JS entry point
296	    // the package's own "main"/"exports" happens to point to, and fall back to
297	    // the separate `@types/<package>` package when the package ships no types
