1	//! Trail 394 spike: oxc vs tsrs parse/bind cost, and oxc_resolver (caliper's config) vs tsrs_module resolution.
2	//! Usage: tsrs-spike <mode> <root> [reps]
3	//!   modes: parse-oxc | parse-tsrs | parse-tsrs-bind | resolve-oxc | resolve-tsrs | resolve-compare
4	//!   <root> holds tsconfig.json and src/; parse modes also take extra dirs via SPIKE_EXTRA (colon separated).
5	
6	use std::path::{Path, PathBuf};
7	use std::time::Instant;
8	
9	use oxc_allocator::Allocator;
10	use oxc_ast::ast::{ModuleDeclaration, Statement};
11	use oxc_parser::Parser;
12	use oxc_resolver::{ResolveOptions, Resolver, TsconfigDiscovery};
13	use oxc_span::SourceType;
14	
15	fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
16	    let Ok(rd) = std::fs::read_dir(dir) else { return };
17	    for e in rd.flatten() {
18	        let p = e.path();
19	        if p.is_dir() {
20	            walk(&p, out);
21	        } else if let Some(n) = p.to_str() {
22	            if n.ends_with(".ts") || n.ends_with(".tsx") || n.ends_with(".mts") || n.ends_with(".cts") {
23	                out.push(p);
24	            }
25	        }
26	    }
27	}
28	
29	fn files(root: &Path, extra: bool) -> Vec<(PathBuf, String)> {
30	    let mut v = Vec::new();
31	    walk(&root.join("src"), &mut v);
32	    if extra {
33	        if let Ok(x) = std::env::var("SPIKE_EXTRA") {
34	            for d in x.split(':') {
35	                walk(Path::new(d), &mut v);
36	            }
37	        }
38	    }
39	    v.sort();
40	    v.into_iter().map(|p| { let s = std::fs::read_to_string(&p).unwrap_or_default(); (p, s) }).collect()
41	}
42	
43	fn specifiers(path: &Path, src: &str) -> Vec<String> {
44	    let alloc = Allocator::default();
45	    let st = SourceType::from_path(path).unwrap_or_default();
46	    let ret = Parser::new(&alloc, src, st).parse();
47	    let mut out = Vec::new();
48	    for s in &ret.program.body {
49	        if let Some(m) = s.as_module_declaration() {
50	            let spec = match m {
51	                ModuleDeclaration::ImportDeclaration(d) => d.source.value.as_str().map(str::to_owned),
52	                ModuleDeclaration::ExportAllDeclaration(d) => d.source.value.as_str().map(str::to_owned),
53	                ModuleDeclaration::ExportFromDeclaration(d) => d.source.value.as_str().map(str::to_owned),
54	                _ => None,
55	            };
56	            out.extend(spec);
57	        }
58	        let _ = matches!(s, Statement::EmptyStatement(_));
59	    }
60	    out
61	}
