63	/// caliper's `resolve_options` (crates/core/src/resolver/mod.rs:710-736), no custom conditions.
64	fn oxc_resolvers() -> (Resolver, Resolver) {
65	    let aliases = |js: &str, ts: &[&str]| (js.to_owned(), ts.iter().map(|e| (*e).to_owned()).collect());
66	    let main = ResolveOptions {
67	        condition_names: ["types", "import", "require", "default"].map(String::from).to_vec(),
68	        main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
69	        extensions: [".ts", ".tsx", ".d.ts", ".d.mts", ".d.cts", ".js"].map(String::from).to_vec(),
70	        extension_alias: vec![
71	            aliases(".js", &[".ts", ".tsx", ".d.ts", ".js"]),
72	            aliases(".jsx", &[".tsx", ".jsx"]),
73	            aliases(".mjs", &[".mts", ".d.mts", ".mjs"]),
74	            aliases(".cjs", &[".cts", ".d.cts", ".cjs"]),
75	        ],
76	        tsconfig: Some(TsconfigDiscovery::Auto),
77	        ..ResolveOptions::default()
78	    };
79	    let tf = ResolveOptions { condition_names: vec!["types".into()], ..main.clone() };
80	    (Resolver::new(main), Resolver::new(tf))
81	}
