83	/// caliper's `resolve_module_with` + `resolve_package_types_file` (resolver/import.rs:288-318, react.rs:115-131).
84	fn oxc_resolve(main: &Resolver, tf: &Resolver, spec: &str, from: &Path) -> Option<String> {
85	    if !spec.starts_with('.') && !spec.starts_with('/') {
86	        let decl = |r: &Resolver, s: &str| {
87	            let res = r.resolve_dts(from, s).ok()?;
88	            let p = res.path().to_string_lossy().into_owned();
89	            ([".d.ts", ".d.mts", ".d.cts"].iter().any(|e| p.ends_with(e)) && res.path().is_file()).then_some(p)
90	        };
91	        let mangled = spec.strip_prefix('@').map_or_else(|| spec.to_owned(), |r| r.replacen('/', "__", 1));
92	        if let Some(p) = decl(main, spec).or_else(|| decl(tf, spec)).or_else(|| decl(main, &format!("@types/{mangled}"))) {
93	            return Some(p);
94	        }
95	    }
96	    main.resolve_file(from, spec).ok().map(|r| r.path().to_string_lossy().into_owned())
97	}
